def row(
    term: str,
    reading: str,
    category: str,
    tags: str,
    short_def: str,
    definition: str,
    related: str,
    legal: str,
    importance: str,
    *,
    detail: str,
    exam_points: list[str],
    mistakes: str,
    memory: str,
    faq1: tuple[str, str],
    faq2: tuple[str, str],
) -> dict[str, str]:
    pts = ";".join(exam_points)
    expl = exam_points[0] if exam_points else short_def
    if len(expl) < 40 and len(exam_points) > 1:
        expl = f"{term}では、{exam_points[1]}を押さえることが重要です。"
    return {
        "term": term,
        "reading": reading,
        "category": category,
        "tags": tags,
        "short_def": short_def,
        "definition": definition,
        "related_terms": related,
        "legal_basis": legal,
        "importance": importance,
        "explanation": (
            f"{term}とは、{short_def.rstrip('。')}。"
            f"試験では{exam_points[0] if exam_points else '定義と要件'}を問われやすいため、"
            "関連用語との違いも合わせて確認してください。"
        ),
        "article_title": f"{term}とは？意味・試験ポイントを整理",
        "article_lead": (
            f"{term}は{category}分野で頻出のキーワードです。"
            f"{short_def.rstrip('。')}点を、試験で迷いやすい条件と合わせて整理します。"
        ),
        "term_detail_body": detail,
        "exam_points": pts,
        "common_mistakes": mistakes,
        "memory_tip": memory,
        "example_question": "",
        "example_answer": "",
        "faq_1_question": faq1[0],
        "faq_1_answer": faq1[1],
        "faq_2_question": faq2[0],
        "faq_2_answer": faq2[1],
        "faq_3_question": "",
        "faq_3_answer": "",
    }


