# fmt: on


def load_existing() -> tuple[list[str], list[dict[str, str]]]:
    text = CSV_PATH.read_text(encoding="utf-8-sig")
    rows = list(csv.DictReader(text.splitlines()))
    fieldnames = list(rows[0].keys()) if rows else BASE_COLS.copy()
    for col in EXTRA_COLS:
        if col not in fieldnames:
            fieldnames.append(col)
    return fieldnames, rows


def main() -> int:
    fieldnames, existing = load_existing()
    existing_terms = {r["term"].strip() for r in existing}
    to_add = [t for t in NEW_TERMS if t["term"] not in existing_terms]
    if not to_add:
        print("No new terms to add (all already present).")
        return 0
    for r in existing:
        for col in EXTRA_COLS:
            r.setdefault(col, "")
    combined = existing + to_add
    with CSV_PATH.open("w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=fieldnames, lineterminator="\n", extrasaction="ignore")
        w.writeheader()
        w.writerows(combined)
    print(f"Added {len(to_add)} terms (total {len(combined)}).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
